-- iClub Economics Gen2 Tours Season 2: single batch, 12 semantic improvements.
-- PREVIEW ONLY until editorial approval; apply at most once after baseline/QA.
-- Existing questions, answers, progress, certificates, and Season 1 are NEVER deleted.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='120s';
DO $economic_revision$
DECLARE
  items jsonb:='[{"ref":"EC9708:G2:EC9708-G2-T1-T-008","d":"medium","k":"B","sec":120,"en":"A bakery can produce 200 loaves a week at the current price. After a 20% price rise it can expand output to 208 loaves in the first week, but to 240 loaves after six months of installing ovens. Using the initial-output percentage change to calculate PES, what are the two elasticities and what explains the difference?","ru":"Пекарня выпускает 200 буханок в неделю. После повышения цены на 20% она может выпустить 208 буханок уже через неделю, а через шесть месяцев после установки печей — 240. Если вычислять PES по изменению количества относительно исходного объёма, каковы две эластичности и почему они отличаются?","uz":"Nonvoyxona haftasiga 200 ta non ishlab chiqaradi. Narx 20% oshgach birinchi haftada 208 ta, yangi pechlar o‘rnatilgach olti oyda 240 ta non ishlab chiqara oladi. PES ni hajmning boshlang‘ich miqdorga nisbatan o‘zgarishidan hisoblang: ikkala elastiklik qancha va nima uchun ular farq qiladi?","options_en":["First week 1.0; after six months 0.2: longer periods reduce flexibility","First week 0.2; after six months 1.0: capacity adjustment makes supply more responsive","First week 0.04; after six months 0.20: PES equals quantity percentage change alone","First week 0.2; after six months 0.2: time cannot affect supply elasticity"],"options_ru":["Первая неделя 1,0; через полгода 0,2: время снижает гибкость","Первая неделя 0,2; через полгода 1,0: расширение мощностей повышает эластичность","Первая неделя 0,04; через полгода 0,20: PES равна только изменению количества","Первая неделя 0,2; через полгода 0,2: время не влияет на эластичность"],"options_uz":["Birinchi hafta 1,0; olti oydan keyin 0,2: vaqt moslashuvni kamaytiradi","Birinchi hafta 0,2; olti oydan keyin 1,0: quvvat oshishi taklifni elastikroq qiladi","Birinchi hafta 0,04; olti oydan keyin 0,20: PES faqat hajm foiziga teng","Birinchi hafta 0,2; olti oydan keyin 0,2: vaqt elastiklikka ta’sir qilmaydi"],"why":["First-week quantity change is 8/200=4%, PES=4%/20%=0.2. Six-month change is 40/200=20%, PES=20%/20%=1.0. More time allows capacity expansion.","За неделю выпуск увеличивается на 8/200=4%, PES=4%/20%=0,2. Через полгода прирост 40/200=20%, PES=1,0. За дополнительное время можно увеличить мощности.","Bir haftada hajm 8/200=4% oshadi, PES=4%/20%=0,2. Olti oyda 40/200=20%, PES=1,0. Ko‘proq vaqt yangi quvvat qurish imkonini beradi."]},{"ref":"EC9708:G2:EC9708-G2-T1-T-015","d":"medium","k":"C","sec":120,"en":"A rescue service has one helicopter and must choose only one trip tonight. Mission A has estimated benefits worth $18,000 and real resource costs of $10,000. Mission B has benefits of $15,000 and costs of $5,000. Ignoring risk and equity differences, which mission has the larger net benefit, and what net benefit is sacrificed by choosing it?","ru":"Спасательная служба располагает одним вертолётом и может выполнить сегодня только один рейс. У рейса A оценочная выгода $18 000 и реальные ресурсные затраты $10 000; у B — выгода $15 000 и затраты $5 000. Если не учитывать различия в рисках и справедливости, какой рейс даёт наибольшую чистую выгоду и какую чистую выгоду теряют при его выборе?","uz":"Qutqaruv xizmatida bitta vertolyot bor va bugun faqat bir qatnovni bajarishi mumkin. A missiyasining baholangan foydasi $18 000, haqiqiy resurs xarajati $10 000; B missiyasida foyda $15 000, xarajat $5 000. Xavf va adolatdagi farqlarni hisoblamasak, qaysi missiyaning sof foydasi katta va uni tanlaganda qaysi sof foydadan voz kechiladi?","options_en":["Choose A; its net benefit is $18,000; opportunity cost $15,000","Choose A; net benefit $8,000; opportunity cost $10,000","Choose B; net benefit $10,000; opportunity cost is A’s forgone $8,000 net benefit","Choose B; net benefit $5,000; opportunity cost is zero because the helicopter is public"],"options_ru":["Выбрать A: чистая выгода $18 000; альтернативная стоимость $15 000","Выбрать A: чистая выгода $8 000; альтернативная стоимость $10 000","Выбрать B: чистая выгода $10 000; упущенная чистая выгода A — $8 000","Выбрать B: чистая выгода $5 000; альтернативная стоимость нулевая, ведь вертолёт государственный"],"options_uz":["A ni tanlash: sof foyda $18 000; muqobil qiymat $15 000","A ni tanlash: sof foyda $8 000; muqobil qiymat $10 000","B ni tanlash: sof foyda $10 000; voz kechilgan A ning sof foydasi $8 000","B ni tanlash: sof foyda $5000; vertolyot davlatniki bo‘lgani uchun muqobil qiymat nol"],"why":["A yields net benefit $18,000−$10,000=$8,000. B yields $15,000−$5,000=$10,000, so B maximises the stated net-benefit objective. The best forgone alternative is A’s $8,000 net benefit; real emergencies may require ethical priorities beyond this calculation.","Чистая выгода A: $18 000−$10 000=$8 000; B: $15 000−$5 000=$10 000. При поставленной цели лучше B, а упущенная чистая выгода A составляет $8 000. В реальных спасательных операциях учитывают также этические приоритеты.","A sof foydasi $18 000−$10 000=$8000; B sof foydasi $15 000−$5000=$10 000. Berilgan mezon bo‘yicha B ustun, voz kechilgan A ning sof foydasi $8000. Haqiqiy qutqaruvda axloqiy ustuvorliklar ham bor."]},{"ref":"EC9708:G2:EC9708-G2-T1-T-017","d":"medium","k":"D","sec":125,"en":"An economy can produce combinations of rice R and shirts S satisfying R/50+S/25≤1 using current resources. It now produces R=20 and S=10. A plan proposes R=40 and S=10 with unchanged resources and technology. Which assessment correctly distinguishes existing spare capacity from an unattainable target?","ru":"При имеющихся ресурсах экономика может выпускать рис R и рубашки S в сочетаниях R/50+S/25≤1. Сейчас она выпускает R=20 и S=10; план требует R=40 и S=10 при неизменных ресурсах и технологии. Какой вывод различает резерв мощностей и недостижимый план?","uz":"Mavjud resurslar bilan iqtisodiyot guruch R va ko‘ylak S ni R/50+S/25≤1 sharti bilan ishlab chiqara oladi. Hozir R=20, S=10, reja esa resurs va texnologiyani o‘zgartirmay R=40, S=10 ni ko‘zlaydi. Qaysi javob bo‘sh quvvat va yetib bo‘lmaydigan rejani to‘g‘ri farqlaydi?","options_en":["Both combinations are outside the PPC, so extra employment cannot help","The planned combination is inside the PPC, and no reallocation is necessary","Current output is on the PPC, but the target can be reached by eliminating unemployment","Current output is inside the PPC (0.8); the plan is beyond it (1.2), so eliminating unused capacity alone cannot achieve the target"],"options_ru":["Обе комбинации вне КПВ, поэтому занятость не поможет","План внутри КПВ и не требует перераспределения","Текущий выпуск на КПВ, а план достижим устранением безработицы","Текущий выпуск внутри КПВ (0,8), план — за пределами (1,2); одного использования резерва недостаточно"],"options_uz":["Ikkala nuqta PPC tashqarisida, shuning uchun ishga joylash yordam bermaydi","Reja PPC ichida, qayta taqsimlash shart emas","Hozirgi hajm PPC ustida, reja ishsizlikni kamaytirib bajariladi","Hozirgi hajm PPC ichida (0,8), reja tashqarida (1,2); faqat bo‘sh resursni ishlatish yetmaydi"],"why":["Current use=20/50+10/25=0.8 (<1), indicating unused potential. Target use=40/50+10/25=1.2 (>1), outside the current PPC. Spare capacity cannot reach a point beyond the frontier.","Сейчас 20/50+10/25=0,8<1 — часть возможностей не используется. Для плана 40/50+10/25=1,2>1 — он за КПВ. Резервных мощностей для такого плана недостаточно.","Hozir 20/50+10/25=0,8<1, ya’ni imkoniyat to‘liq ishlatilmagan. Reja 40/50+10/25=1,2>1, PPC tashqarisida. Bo‘sh quvvatning o‘zi yetarli emas."]},{"ref":"EC9708:G2:EC9708-G2-T1-T-020","d":"medium","k":"B","sec":120,"en":"A school contract increases daily demand for bread by 300 loaves. Bakeries can supply 50 of those loaves from existing finished-goods inventory; the remaining 250 must be baked. Each new loaf uses 0.5 kg of flour. Assuming flour stocks do not change and no wastage, how much does the bakeries’ daily demand for flour increase, and why?","ru":"Школьный контракт увеличивает дневной спрос на хлеб на 300 буханок. Пекарни могут отгрузить 50 буханок из запаса готовой продукции, остальные 250 нужно испечь. На каждую новую буханку уходит 0,5 кг муки. При неизменных запасах муки и без потерь на сколько возрастёт дневной спрос пекарен на муку и почему?","uz":"Maktab shartnomasi nonga kundalik talabni 300 dona oshiradi. Nonvoyxonalar 50 donasini tayyor mahsulot zaxirasidan bera oladi, qolgan 250 donani pishirish kerak. Har yangi non uchun 0,5 kg un ketadi. Un zaxirasi o‘zgarmasa va yo‘qotish bo‘lmasa, unga kunlik talab qancha oshadi va nima uchun?","options_en":["150 kg; flour demand equals the entire increase in finished bread demand","125 kg; flour demand is derived from the 250 additional loaves actually produced","25 kg; only the inventory loaves need extra flour","600 kg; bread output must double flour demand"],"options_ru":["150 кг; мука нужна на весь прирост спроса на готовый хлеб","125 кг; производный спрос на муку связан с 250 дополнительно испечёнными буханками","25 кг; дополнительная мука нужна только для хлеба из запасов","600 кг; выпуск хлеба обязательно удваивает потребность в муке"],"options_uz":["150 kg; un talabi tayyor non talabining butun o‘sishiga teng","125 kg; un talabi ishlab chiqarilgan qo‘shimcha 250 nonga bog‘liq hosilaviy talab","25 kg; faqat ombordagi non uchun qo‘shimcha un kerak","600 kg; non ishlab chiqarish un talabini albatta ikki baravar qiladi"],"why":["Additional current production is 300−50=250 loaves. Derived flour demand rises 250×0.5kg=125kg; finished inventory meets part of demand without new flour input.","Дополнительно производится 300−50=250 буханок. Производный спрос на муку увеличивается на 250×0,5=125 кг. Готовый складской хлеб не требует новой муки.","Qo‘shimcha ishlab chiqarish 300−50=250 non. Undan hosila talab 250×0,5=125 kg oshadi. Ombordagi tayyor non uchun yangi un kerak emas."]},{"ref":"EC9708:G2:EC9708-G2-T3-T-012","d":"medium","k":"B","sec":125,"en":"Before transport costs, each of 250 traded units yields an estimated total gain from specialisation of $14 shared between two countries. International freight costs $9 per unit and border handling consumes a further $3 per unit in real resources. Assuming these are the only trading costs and all units are traded, what is the net aggregate gain and what principle does it illustrate?","ru":"До учёта перевозки специализация и торговля 250 единицами дают двум странам общую оценочную выгоду $14 с единицы. Международная перевозка расходует $9, а обработка на границе — ещё $3 реальных ресурсов на единицу. Других затрат нет, все 250 единиц продаются. Каков общий чистый выигрыш и что он показывает?","uz":"Transport xarajatlarisiz 250 birlikdagi ixtisoslashuv va savdo ikki mamlakatga har birlik uchun jami $14 foyda beradi. Xalqaro tashish har birlikka $9, chegara ishlovi yana $3 real resurs sarflaydi. Boshqa xarajat yo‘q, 250 birlik savdo qilinadi. Jami sof foyda qancha va bu nimani ko‘rsatadi?","options_en":["$3,500; comparative advantage makes freight cost irrelevant","$500; real trade costs can reduce—but here do not eliminate—gains from specialisation","$750; only the handling cost should be deducted","−$500; international trade is always harmful when freight exists"],"options_ru":["$3 500; сравнительное преимущество делает перевозку бесплатной","$500; реальные торговые издержки уменьшают, но здесь не уничтожают выигрыш от специализации","$750; нужно вычесть только пограничную обработку","−$500; внешняя торговля всегда вредна при наличии фрахта"],"options_uz":["$3500; nisbiy ustunlikda tashish xarajati ahamiyatsiz","$500; real savdo xarajatlari ixtisoslashuv foydasini kamaytiradi, lekin bu yerda yo‘q qilmaydi","$750; faqat chegara ishlovi xarajati ayiriladi","−$500; tashish xarajati bo‘lsa tashqi savdo doim zararli"],"why":["Net gain per traded unit=$14−$9−$3=$2; 250×$2=$500. Comparative advantage may produce gains, but shipping and other real costs determine whether trade remains worthwhile.","Чистая выгода на единицу $14−$9−$3=$2; всего 250×$2=$500. Сравнительное преимущество не отменяет реальных транспортных издержек.","Bir birlik sof foyda $14−$9−$3=$2; jami 250×$2=$500. Nisbiy ustunlik mavjud bo‘lsa ham, real transport va chegara xarajatlarini hisoblash zarur."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-011","d":"medium","k":"A","sec":120,"en":"Two grocery chains used to operate 20 delivery routes per week at a cost of $100 per route. After merging warehouses they need only 12 routes, but each now costs $120, plus an extra $200 a week of coordination costs. Assuming service quality and output stay unchanged, how much do weekly distribution costs fall and what efficiency mechanism is involved?","ru":"Две продуктовые сети раньше обслуживали 20 маршрутов доставки в неделю по $100 за маршрут. После объединения складов нужно только 12 маршрутов, каждый теперь стоит $120, плюс $200 в неделю на координацию. Качество обслуживания и объём продаж неизменны. На сколько уменьшаются недельные издержки и за счёт какого механизма?","uz":"Ikki oziq-ovqat tarmog‘i ilgari haftasiga 20 yetkazish yo‘nalishini har biri $100 dan bajargan. Omborlarni birlashtirgach 12 yo‘nalish qoladi, har biri $120, qo‘shimcha muvofiqlashtirish haftasiga $200 turadi. Xizmat sifati va hajmi o‘zgarmaydi. Haftalik xarajat qancha kamayadi va bu qaysi samaradorlik mexanizmi?","options_en":["$360 saved; removing duplicate routes may generate economies of scale or scope","$560 saved; coordination costs must not be counted","$800 saved; delivery costs remain $100 after merging","$1,440 saved; all costs become zero after merging"],"options_ru":["Экономия $360; устранение дублирующихся маршрутов может дать экономию масштаба или охвата","Экономия $560; координационные затраты не учитывают","Экономия $800; доставка по-прежнему стоит $100","Экономия $1 440; после объединения все затраты обнуляются"],"options_uz":["Tejam $360; takroriy yo‘nalishlarni yo‘qotish miqyos yoki ko‘lam tejamkorligini yaratishi mumkin","Tejam $560; muvofiqlashtirish xarajati hisobga olinmaydi","Tejam $800; yetkazish har doim $100 qoladi","Tejam $1440; birlashgach barcha xarajat nol bo‘ladi"],"why":["Old cost=20×$100=$2,000 per week. New cost=12×$120+$200=$1,640. Saving=$360. Operational integration can lower unit costs; consumer price changes are not guaranteed.","Раньше затраты 20×$100=$2 000 в неделю. Теперь 12×$120+$200=$1 640, экономия $360. Объединение снижает издержки, но не гарантирует снижение цены для покупателей.","Avval 20×$100=$2000/hafta. Keyin 12×$120+$200=$1640, tejam $360. Birlashish xarajatni kamaytirishi mumkin, ammo iste’molchi narxi tushishi shart emas."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-013","d":"medium","k":"D","sec":125,"en":"A manufacturer spends $1.2m on original process R&D today. It expects the innovation to save $0.4m of real production resources each year for four years. Ignoring discounting, other impacts and maintenance, what is the net resource benefit over the period, and which efficiency concept best describes the improvement?","ru":"Производитель сегодня тратит $1,2 млн на исследования нового процесса. Ожидается, что нововведение будет экономить по $0,4 млн реальных производственных ресурсов ежегодно в течение четырёх лет. Без дисконтирования, обслуживания и других эффектов какова чистая выгода за период и какой вид эффективности отражён?","uz":"Ishlab chiqaruvchi bugun yangi jarayon uchun $1,2 mln tadqiqot xarajati qiladi. Yangilik to‘rt yil davomida har yili $0,4 mln real ishlab chiqarish resursini tejashi kutiladi. Diskontlash, texnik xizmat va boshqa ta’sirlarsiz davrning sof foydasi qancha va bu qaysi samaradorlik turi?","options_en":["−$0.4m; static allocative efficiency","$1.6m; current monopoly profit only","+$1.2m; productive efficiency is guaranteed today","+$0.4m; dynamic efficiency from innovation over time"],"options_ru":["−$0,4 млн; статическая аллокативная эффективность","+$1,6 млн; только текущая монопольная прибыль","+$1,2 млн; производственная эффективность гарантирована уже сегодня","+$0,4 млн; динамическая эффективность благодаря инновации во времени"],"options_uz":["−$0,4 mln; statik taqsimlash samaradorligi","+$1,6 mln; faqat hozirgi monopol foyda","+$1,2 mln; ishlab chiqarish samaradorligi bugun kafolatlangan","+$0,4 mln; vaqt o‘tishi bilan innovatsiyadan dinamik samaradorlik"],"why":["Undiscounted resource savings total 4×$0.4m=$1.6m. Less R&D cost $1.2m gives +$0.4m. Dynamic efficiency concerns innovation and improved products or processes over time, not guaranteed present allocative efficiency.","Экономия 4×$0,4 млн=$1,6 млн. За вычетом исследований $1,2 млн чистый результат +$0,4 млн. Динамическая эффективность возникает через инновации со временем.","Tejam 4×$0,4 mln=$1,6 mln. $1,2 mln tadqiqot xarajati ayirilgach sof +$0,4 mln. Dinamik samaradorlik vaqt o‘tishi bilan innovatsiya natijasidir."]},{"ref":"EC9708:G2:EC9708-G2-T4-T-020","d":"medium","k":"B","sec":125,"en":"Two airlines choose simultaneously to hold or cut fares on the only city route. If both hold, each earns $9m. If one cuts alone it earns $12m while the other earns $3m. If both cut, each earns $5m. Assuming each airline maximises only its own stated one-period profit, what is the Nash equilibrium and why is it less profitable jointly than mutual restraint?","ru":"Две авиакомпании одновременно выбирают, сохранить или снизить тарифы на единственном маршруте. Если обе сохраняют тарифы, каждая зарабатывает $9 млн. Если одна снижает тариф, она получает $12 млн, а другая $3 млн. Если обе снижают, каждая получает $5 млн. При максимизации только собственной прибыли за один период каково равновесие Нэша и почему оно менее выгодно вместе?","uz":"Ikki aviakompaniya yagona yo‘nalishda bir vaqtda narxni saqlash yoki pasaytirishni tanlaydi. Ikkalasi saqlasa har biri $9 mln oladi. Faqat bittasi tushirsa u $12 mln, ikkinchisi $3 mln oladi. Ikkalasi tushirsa har biri $5 mln oladi. Har biri faqat bir davrlik o‘z foydasini maksimal qilsa Nash muvozanati qanday va nega u umumiy jihatdan kam foydali?","options_en":["Both hold; holding is always the dominant strategy","Both cut; each has an incentive to cut regardless of the rival, despite earning only $5m each instead of $9m","One holds while the other cuts; both earn $12m","Both cut; each earns $9m because profits cannot change"],"options_ru":["Обе сохраняют тариф; сохранение всегда доминирует","Обе снижают: каждой выгодно снизить независимо от соперника, хотя доход $5 млн вместо $9 млн при взаимной сдержанности","Одна сохраняет, другая снижает; обе получают $12 млн","Обе снижают; каждая всё равно получает $9 млн"],"options_uz":["Ikkalasi narxni saqlaydi; saqlash doim ustun strategiya","Ikkalasi tushiradi: raqib qaroridan qat’i nazar tushirish foydaliroq, ammo har biri $9 mln o‘rniga $5 mln oladi","Bittasi saqlaydi, boshqasi tushiradi; ikkalasi $12 mln oladi","Ikkalasi tushiradi; har biri baribir $9 mln oladi"],"why":["Against a hold decision, cutting yields 12>9. Against a cut decision, cutting yields 5>3. Cutting dominates for each player, producing a (cut,cut) Nash equilibrium with $5m each, below the jointly higher $9m-each hold outcome.","Если конкурент сохраняет тариф, снизить выгоднее (12>9); если снижает — тоже выгоднее (5>3). Оба снизят, получив по $5 млн вместо $9 млн при взаимном сохранении.","Raqib saqlasa tushirish foydali (12>9), raqib tushirsa ham tushirish foydali (5>3). Nash muvozanatida ikkalasi tushiradi va $5 mln oladi, saqlashdagi $9 mln dan kam."]},{"ref":"EC9708:G2:EC9708-G2-T6-T-015","d":"medium","k":"A","sec":120,"en":"A labour force has 500,000 workers, including 10,000 frictionally unemployed, 15,000 structurally unemployed and 20,000 cyclically unemployed people; all categories are distinct. If an economic recovery eliminates cyclical unemployment only, what are the initial unemployment rate and the unemployment rate remaining at the natural-rate benchmark?","ru":"Рабочая сила насчитывает 500 000 человек, включая 10 000 фрикционных, 15 000 структурных и 20 000 циклических безработных; группы не пересекаются. Если восстановление экономики устраняет только циклическую безработицу, каковы первоначальный уровень безработицы и оставшийся уровень на естественном ориентире?","uz":"Mehnat kuchida 500 000 kishi bor; 10 000 friksion, 15 000 tarkibiy va 20 000 davriy ishsiz, guruhlar kesishmaydi. Iqtisodiy tiklanish faqat davriy ishsizlikni yo‘qotsa, dastlabki ishsizlik va tabiiy darajadagi qolgan ishsizlik necha foiz?","options_en":["Initially 9%; natural-rate benchmark 5%","Initially 5%; natural-rate benchmark 9%","Initially 9%; natural-rate benchmark 0%","Initially 4%; natural-rate benchmark 5%"],"options_ru":["Сначала 9%; естественный ориентир 5%","Сначала 5%; естественный ориентир 9%","Сначала 9%; естественный ориентир 0%","Сначала 4%; естественный ориентир 5%"],"options_uz":["Dastlab 9%; tabiiy daraja 5%","Dastlab 5%; tabiiy daraja 9%","Dastlab 9%; tabiiy daraja 0%","Dastlab 4%; tabiiy daraja 5%"],"why":["Initially (10,000+15,000+20,000)/500,000=9%. After the cyclical part disappears, (10,000+15,000)/500,000=5% remains because frictional and structural unemployment need not vanish in a recovery.","Первоначально (10 000+15 000+20 000)/500 000=9%. После устранения циклической части (10 000+15 000)/500 000=5%; фрикционная и структурная безработица остаются.","Dastlab (10 000+15 000+20 000)/500 000=9%. Davriy qism yo‘qolgach (10 000+15 000)/500 000=5% qoladi; friksion va tarkibiy sabablar saqlanadi."]},{"ref":"EC9708:G2:EC9708-G2-T6-T-016","d":"medium","k":"C","sec":125,"en":"An economy has potential real output of $1,000bn and actual output of $900bn. To reduce demand-pull inflation from 6% to 4%, the central bank raises interest rates; actual output falls by a further $20bn, while potential output stays fixed. Define the output gap as (actual−potential)/potential. What happens to the gap and the rate of inflation?","ru":"Потенциальный реальный выпуск экономики равен $1 000 млрд, фактический — $900 млрд. Для снижения инфляции спроса с 6% до 4% центральный банк повышает ставки; фактический выпуск падает ещё на $20 млрд, потенциал неизменен. Разрыв выпуска определяется как (фактический−потенциальный)/потенциальный. Как меняются разрыв и темп инфляции?","uz":"Iqtisodiyotda potensial real ishlab chiqarish $1000 mlrd, haqiqiy ishlab chiqarish $900 mlrd. Talab inflyatsiyasini 6% dan 4% ga pasaytirish uchun markaziy bank stavkani oshiradi; haqiqiy ishlab chiqarish yana $20 mlrd kamayadi, potensial hajm o‘zgarmaydi. Ishlab chiqarish tafovuti (haqiqiy−potensial)/potensial. Tafovut va inflyatsiya sur’ati qanday o‘zgaradi?","options_en":["Gap −10%→−8%; 4% inflation means deflation","Gap −10%→−12%; falling inflation means prices fall overall","Gap −10%→−12%; inflation slows but stays positive as the negative output gap widens","Gap +10%→+12%; the economy overheats further"],"options_ru":["Разрыв −10%→−8%; инфляция 4% означает дефляцию","Разрыв −10%→−12%; снижение инфляции означает общее падение цен","Разрыв −10%→−12%; инфляция замедляется, но остаётся положительной, отрицательный разрыв расширяется","Разрыв +10%→+12%; экономика ещё сильнее перегревается"],"options_uz":["Tafovut −10%→−8%; 4% inflyatsiya deflyatsiyani bildiradi","Tafovut −10%→−12%; inflyatsiya pasayishi umumiy narx tushishini bildiradi","Tafovut −10%→−12%; inflyatsiya sekinlashadi, lekin musbat qoladi, manfiy ishlab chiqarish tafovuti kengayadi","Tafovut +10%→+12%; iqtisodiyot yanada qizib ketadi"],"why":["Initially the gap is (900−1,000)/1,000=−10%. After monetary tightening, output is $880bn, so the gap is (880−1,000)/1,000=−12%. Inflation of 4% is still positive (disinflation), while the larger negative gap illustrates the output cost of restraining demand.","Изначальный разрыв (900−1 000)/1 000=−10%. После ужесточения политики выпуск $880 млрд, новый разрыв (880−1 000)/1 000=−12%. При инфляции 4% цены продолжают расти (дезинфляция); увеличение отрицательного разрыва показывает цену сдерживания спроса.","Dastlab tafovut (900−1000)/1000=−10%. Pul siyosati qat’iylashgach ishlab chiqarish $880 mlrd, tafovut (880−1000)/1000=−12%. Inflyatsiya 4% bo‘lsa narxlar hali oshmoqda (dezinflyatsiya); manfiy tafovutning kengayishi talabni cheklash xarajatini ko‘rsatadi."]},{"ref":"EC9708:G2:EC9708-G2-T7-T-013","d":"medium","k":"D","sec":130,"en":"Countries A and B each report annual GDP per person of $25,000. For a deliberately simplified welfare comparison, independently valued non-market leisure is $2,000 per person in A and $700 in B, while measured pollution harm is $1,000 in A and $2,500 in B. Assuming comparable valuations and no other differences, what are their adjusted welfare proxies, and what is the limitation?","ru":"Страны A и B имеют одинаковый ВВП на человека — $25 000. Для упрощённого сравнения благосостояния независимая денежная оценка досуга составляет $2 000 на человека в A и $700 в B, а ущерб от загрязнения — $1 000 в A и $2 500 в B. Если оценки сопоставимы и прочих различий нет, чему равны скорректированные показатели благосостояния и в чём их ограничение?","uz":"A va B mamlakatlarning jon boshiga YaIMi $25 000. Soddalashtirilgan farovonlik taqqoslashda bozor orqali o‘lchanmagan bo‘sh vaqt qiymati A da $2000, B da $700; ifloslanish zarari A da $1000, B da $2500. Baholar taqqoslanadigan va boshqa farq yo‘q bo‘lsa, tuzatilgan farovonlik ko‘rsatkichlari qanday va ularning cheklovi nima?","options_en":["A $27,000, B $25,700; GDP already includes all environmental harm","A $24,000, B $22,500; leisure must never be included","A $26,000, B $23,200; valuations establish precise overall life satisfaction","A $26,000, B $23,200; this proxy captures selected non-market effects, not all dimensions of welfare"],"options_ru":["A $27 000, B $25 700; ВВП уже включает весь экологический ущерб","A $24 000, B $22 500; досуг учитывать нельзя","A $26 000, B $23 200; оценки точно измеряют всё жизненное удовлетворение","A $26 000, B $23 200; показатель включает лишь некоторые нерыночные эффекты"],"options_uz":["A $27 000, B $25 700; YaIM barcha ekologik zararni allaqachon qamraydi","A $24 000, B $22 500; bo‘sh vaqt umuman hisoblanmaydi","A $26 000, B $23 200; bu ko‘rsatkich butun hayot mamnunligini aniq belgilaydi","A $26 000, B $23 200; bu faqat ayrim nobozor ta’sirlarni hisoblaydigan ko‘rsatkich"],"why":["A proxy: $25,000+$2,000−$1,000=$26,000. B proxy: $25,000+$700−$2,500=$23,200. It shows how selected non-market costs and benefits can change comparisons but is not a complete welfare or happiness index.","A: $25 000+$2 000−$1 000=$26 000; B: $25 000+$700−$2 500=$23 200. Некоторые нерыночные выгоды и издержки меняют сравнение, но показатель не охватывает всё благосостояние.","A: $25 000+$2000−$1000=$26 000; B: $25 000+$700−$2500=$23 200. Ayrim nobozor foyda va zararni kiritish natijani o‘zgartiradi, lekin farovonlikning hamma tomonini qamramaydi."]},{"ref":"EC9708:G2:EC9708-G2-T7-T-015","d":"medium","k":"A","sec":130,"en":"Two countries have dimension index values for income, health and education. Country A has 0.90, 0.50 and 0.50; Country B has 0.75, 0.75 and 0.75. In a simplified HDI-style calculation using the geometric mean of these three indices, which country ranks higher, and why can A’s higher income index fail to make its overall score higher?","ru":"Для двух стран известны индексы дохода, здоровья и образования. В A это 0,90, 0,50 и 0,50; в B — 0,75, 0,75 и 0,75. В упрощённом расчёте по принципу ИЧР, где берут геометрическое среднее трёх индексов, какая страна выше и почему преимущество A по доходам не гарантирует итоговое преимущество?","uz":"Ikki mamlakatning daromad, sog‘liq va ta’lim indekslari berilgan. A da 0,90, 0,50 va 0,50; B da 0,75, 0,75 va 0,75. Uch indeks geometrik o‘rtachasi olinadigan soddalashtirilgan HDI usulida qaysi mamlakat yuqori va nima uchun A ning daromad indeksi ustunligi yetarli emas?","options_en":["B: geometric mean 0.75 versus approximately 0.61 in A, because weaker health and education reduce A’s overall score","A: geometric mean 0.90, because the income dimension overrides the others","Both: the income index alone determines the overall measure","A: geometric mean 1.90 because all three indices must be added"],"options_ru":["B: геометрическое среднее 0,75 против примерно 0,61 у A; слабые здоровье и образование снижают итог A","A: геометрическое среднее 0,90, поскольку доход имеет абсолютный приоритет","Равенство: общий показатель определяется только доходом","A: геометрическое среднее 1,90, поскольку индексы нужно сложить"],"options_uz":["B: geometrik o‘rtacha 0,75; A da taxminan 0,61; salomatlik va ta’limning pastligi A ni pasaytiradi","A: geometrik o‘rtacha 0,90, chunki daromad hammasidan ustun","Teng: umumiy indeks faqat daromadga bog‘liq","A: geometrik o‘rtacha 1,90, chunki uch indeks qo‘shiladi"],"why":["A index=(0.90×0.50×0.50)^(1/3)≈0.608; B=(0.75³)^(1/3)=0.75. The HDI-style geometric mean combines dimensions, so higher income alone cannot compensate fully for substantially weaker health and education.","У A (0,90×0,50×0,50)^(1/3)≈0,608; у B (0,75³)^(1/3)=0,75. Геометрическое среднее учитывает несколько измерений, и высокий доход не отменяет недостатков здоровья и образования.","A da (0,90×0,50×0,50)^(1/3)≈0,608, B da (0,75³)^(1/3)=0,75. Geometrik o‘rtacha turli o‘lchamlarni birlashtiradi, shuning uchun yuqori daromad sog‘liq va ta’limdagi kamchilikni to‘liq qoplamaydi."]}]'::jsonb;
  x jsonb; oldq record; new_question_id bigint; correct_idx int; j int;
  reftext text; keytext text; newref text;
  itemcount int; v_count int; n int; ez int; med int; hard int;
  this_tour_no int; tour_numbers int[]:=ARRAY[1,3,4,6,7];
  expected_by_tour jsonb:='{"1":4,"3":1,"4":3,"6":2,"7":2}'::jsonb;
BEGIN
  IF jsonb_array_length(items) <> 12 THEN RAISE EXCEPTION 'editorial_item_count_mismatch'; END IF;
  -- All five Season 2 Tours have no learner activity. Check across entire Season 2 too.
  IF EXISTS (
    SELECT 1 FROM public.tour_attempts a JOIN public.tours t ON t.id=a.tour_id
    WHERE t.subject_id=7 AND t.season_id=2
  ) THEN RAISE EXCEPTION 'season_2_tour_attempt_exists_stop_release'; END IF;
  FOR this_tour_no IN SELECT unnest(tour_numbers) LOOP
    SELECT COUNT(*) INTO n FROM public.tours t
      JOIN public.tour_questions l ON l.tour_id=t.id AND l.is_active
    WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=this_tour_no;
    IF n<>20 THEN RAISE EXCEPTION 'tour_%_pool_size_changed_%',this_tour_no,n; END IF;
    SELECT COUNT(*) INTO itemcount FROM jsonb_array_elements(items) AS e(value)
    WHERE e.value->>'ref' LIKE 'EC9708:G2:EC9708-G2-T'||this_tour_no||'-T-%';
    IF itemcount<>(expected_by_tour->>this_tour_no::text)::int
    THEN RAISE EXCEPTION 'tour_%_replacement_count_changed',this_tour_no; END IF;
  END LOOP;
  FOR x IN SELECT value FROM jsonb_array_elements(items) LOOP
    reftext:=x->>'ref'; newref:=reftext||'-V2'; keytext:=x->>'k';
    correct_idx:=ascii(keytext)-65;
    IF reftext !~ '^EC9708:G2:EC9708-G2-T(1|3|4|6|7)-T-[0-9]{3}$'
       OR keytext NOT IN ('A','B','C','D') OR x->>'d'<>'medium'
       OR (x->>'sec')::int NOT BETWEEN 90 AND 135
       OR jsonb_array_length(x->'options_en')<>4
       OR jsonb_array_length(x->'options_ru')<>4
       OR jsonb_array_length(x->'options_uz')<>4
       OR jsonb_array_length(x->'why')<>3
       OR length(trim(coalesce(x->>'en','')))<60
       OR length(trim(coalesce(x->>'ru','')))<60
       OR length(trim(coalesce(x->>'uz','')))<60
    THEN RAISE EXCEPTION 'invalid_editorial_payload_%',reftext; END IF;
    SELECT q.id,q.subject_id,q.topic,q.subtopic,q.qtype,q.difficulty,q.quality_flag,
           l.tour_id,l.order_no,t.season_id
       INTO STRICT oldq
       FROM public.questions q JOIN public.tour_questions l ON l.question_id=q.id AND l.is_active
       JOIN public.tours t ON t.id=l.tour_id
       WHERE q.subject_id=7 AND t.subject_id=7 AND t.season_id=2
         AND q.book_ref=reftext;
    IF oldq.difficulty<>'medium' OR oldq.qtype<>'mcq'
    THEN RAISE EXCEPTION 'original_changed_%',reftext; END IF;
    IF EXISTS(SELECT 1 FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=newref)
       OR EXISTS(SELECT 1 FROM public.tour_answers a WHERE a.question_id=oldq.id)
       OR EXISTS(SELECT 1 FROM public.tour_session_answers_v4 a WHERE a.question_id=oldq.id)
       OR EXISTS(SELECT 1 FROM public.practice_answers a WHERE a.question_id=oldq.id)
    THEN RAISE EXCEPTION 'history_or_version_conflict_%',reftext; END IF;
    INSERT INTO public.questions (
       subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,
       explanation,image_url,is_active,question_text_ru,question_text_uz,question_text_en,
       options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,
       explanation_en,book_ref,time_limit_sec,quality_flag,quality_status
    ) VALUES (
       oldq.subject_id,oldq.topic,oldq.subtopic,'medium','mcq',x->>'en',(x->'options_en')::text,
       keytext,'Correct answer: '||(x->'options_en'->>correct_idx)||E'\n'||(x->'why'->>0),
       NULL,true,x->>'ru',x->>'uz',x->>'en',(x->'options_ru')::text,
       (x->'options_uz')::text,(x->'options_en')::text,
       'Правильный ответ: '||(x->'options_ru'->>correct_idx)||E'\n'||(x->'why'->>1),
       'To‘g‘ri javob: '||(x->'options_uz'->>correct_idx)||E'\n'||(x->'why'->>2),
       'Correct answer: '||(x->'options_en'->>correct_idx)||E'\n'||(x->'why'->>0),
       newref,(x->>'sec')::int,oldq.quality_flag,'published'
    ) RETURNING id INTO new_question_id;
    UPDATE public.tour_questions SET is_active=false
      WHERE tour_id=oldq.tour_id AND question_id=oldq.id AND is_active;
    GET DIAGNOSTICS n=ROW_COUNT;
    IF n<>1 THEN RAISE EXCEPTION 'old_active_link_count_changed_%',reftext; END IF;
    INSERT INTO public.tour_questions(tour_id,question_id,order_no,is_active)
       VALUES(oldq.tour_id,new_question_id,oldq.order_no,true);
    INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
       VALUES(oldq.id,new_question_id,'replacement',
         'Economics Gen2 Season2 batch: original medium-level reasoning replacing recall-only item');
    FOR j IN 0..3 LOOP
      INSERT INTO public.question_answer_diagnostics (
        question_id,answer_kind,answer_key,answer_value,is_correct,mistake_type,weak_skill,
        feedback_ru,feedback_uz,feedback_en,next_action_ru,next_action_uz,next_action_en,
        rule_json,quality_status
      ) VALUES (
        new_question_id,'mcq_option',chr(65+j),NULL,j=correct_idx,
        CASE WHEN j=correct_idx THEN NULL ELSE 'multi_step_economic_reasoning' END,
        oldq.subtopic,
        'Выбрано: '||(x->'options_ru'->>j)||E'\n'||(x->'why'->>1)||E'\nОтвет: '||(x->'options_ru'->>correct_idx),
        'Tanlov: '||(x->'options_uz'->>j)||E'\n'||(x->'why'->>2)||E'\nJavob: '||(x->'options_uz'->>correct_idx),
        'Selected: '||(x->'options_en'->>j)||E'\n'||(x->'why'->>0)||E'\nCorrect: '||(x->'options_en'->>correct_idx),
        CASE WHEN j=correct_idx THEN NULL ELSE 'Проверьте каждый шаг рассуждения.' END,
        CASE WHEN j=correct_idx THEN NULL ELSE 'Mulohazaning har bir bosqichini tekshiring.' END,
        CASE WHEN j=correct_idx THEN NULL ELSE 'Check each reasoning step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_BATCH_'||replace(split_part(reftext,':',3),'-','_')||'_V2_'||chr(65+j)),
        'published');
    END LOOP;
  END LOOP;
  -- Strict postconditions: do not change the seven Tour difficulty allocations.
  FOR this_tour_no IN SELECT unnest(tour_numbers) LOOP
    SELECT COUNT(*),COUNT(*) FILTER (WHERE q.difficulty='easy'),
       COUNT(*) FILTER (WHERE q.difficulty='medium'),COUNT(*) FILTER (WHERE q.difficulty='hard')
    INTO n,ez,med,hard FROM public.tours t JOIN public.tour_questions l
      ON l.tour_id=t.id AND l.is_active
      JOIN public.questions q ON q.id=l.question_id
    WHERE t.subject_id=7 AND t.season_id=2 AND t.tour_no=this_tour_no;
    IF n<>20 OR ez<>6 OR med<>10 OR hard<>4
    THEN RAISE EXCEPTION 'tour_%_final_mix_failed_%_%_%_%',this_tour_no,n,ez,med,hard; END IF;
  END LOOP;
  SELECT COUNT(*) INTO v_count FROM public.questions q
  WHERE q.subject_id=7 AND q.book_ref IN
    (SELECT (value->>'ref')||'-V2' FROM jsonb_array_elements(items));
  IF v_count<>12 THEN RAISE EXCEPTION 'version_count_failed_%',v_count; END IF;
  SELECT COUNT(*) INTO n FROM public.question_answer_diagnostics d
    JOIN public.questions q ON q.id=d.question_id
  WHERE q.subject_id=7 AND q.book_ref IN
    (SELECT (value->>'ref')||'-V2' FROM jsonb_array_elements(items));
  IF n<>48 THEN RAISE EXCEPTION 'diagnostic_count_failed_%',n; END IF;
END $economic_revision$;
COMMIT;